.side-bottom{margin-top:auto;color:#6b6a7c;font-size:8px;letter-spacing:1px}.online{color:#aaa9b9;font-size:9px;margin-bottom:9px}.online i{background:var(--cyan);width:5px;height:5px}.main-view{min-width:0;padding:24px 30px 30px;max-width:1600px;width:100%;margin:0 auto}.view-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:19px}.eyebrow{font-size:9px;letter-spacing:2px;color:var(--gold);margin-bottom:7px}.view-heading h1{font:25px var(--serif);margin:0;letter-spacing:.5px}.heading-note{font-size:10px;color:var(--muted);margin-top:5px}.mode-tabs{display:flex;gap:7px}.mode-tab{font-size:10px;color:#8f8e9f;border:1px solid var(--line);background:#191a27;border-radius:4px;padding:8px 13px;letter-spacing:.4px}.mode-tab.selected{color:var(--gold);border-color:#8e7547;background:#292536}.battle-grid{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:17px}.arena{height:419px;position:relative;overflow:hidden;border:1px solid rgba(227,204,165,.18);border-radius:9px;background:linear-gradient(180deg,#242039 0%,#30263c 43%,#201d30 68%,#151723 100%);box-shadow:0 14px 40px #0003}.arena:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 52%,rgba(219,105,159,.16),transparent 34%),radial-gradient(ellipse at 20% 39%,#8c6b8d24,transparent 23%),linear-gradient(180deg,transparent 50%,#11131e8c);pointer-events:none}.arena-stars{position:absolute;inset:0;opacity:.5;background-image:radial-gradient(1px 1px at 14% 21%,#fff,transparent),radial-gradient(1px 1px at 73% 18%,#eacda9,transparent),radial-gradient(1.5px 1.5px at 52% 11%,#fff,transparent),radial-gradient(1px 1px at 87% 35%,#fff,transparent),radial-gradient(1px 1px at 30% 43%,#d1a3d8,transparent)}.moon{position:absolute;top:37px;left:calc(50% - 33px);width:66px;height:66px;border-radius:50%;background:radial-gradient(circle at 38% 38%,#e9cbdc,#9981a6 62%,#614f76);box-shadow:0 0 44px #e1b5df35;opacity:.57}.ruin{position:absolute;bottom:115px;height:119p