flex;align-items:flex-end;justify-content:center}.enemy .portrait-wrap{height:95px}.portrait{height:100px;width:90px;display:block;filter:drop-shadow(0 8px 12px #08080bb3)}.enemy .portrait{height:96px;width:90px}.fighter-name{font-size:10px;font-weight:600;text-shadow:0 1px 4px #000;white-space:nowrap}.fighter-role{font-size:8px;color:#c5b8c5;margin-top:2px}.hp-track{height:5px;background:#15151d;border-radius:5px;margin:6px 9px 0;overflow:hidden;border:1px solid #ffffff24}.hp-fill{height:100%;background:linear-gradient(90deg,#d65c7e,#f28a9d);border-radius:5px;transition:width .4s}.ally .hp-fill{background:linear-gradient(90deg,#42a99e,#84e5d4)}.fighter-meta{display:flex;justify-content:space-between;margin:3px 9px 0;font-size:8px;color:#c7c1ce}.status-row{height:13px;display:flex;justify-content:center;gap:3px;margin-top:3px}.status-chip{font-size:8px;border-radius:8px;padding:1px 5px;background:#272d3c;color:var(--cyan)}.element-badge{position:absolute;top:22px;right:14px;border:1px solid #ffffff4d;color:#fff;background:#151522a8;width:19px;height:19px;border-radius:50%;font-size:10px;display:grid;place-items:center}.turn-marker{position:absolute;top:-8px;left:calc(50% - 5px);height:7px;width:7px;border-radius:50%;background:var(--gold);box-shadow:0 0 10px var(--gold)}.damage-float{position:absolute;top:10px;left:50%;font:bold 20px var(--serif);color:#fff4d0;text-shadow:0 2px 8px #f45268;animation:floatup .9s forwards;z-index:4;pointer-events:none}@keyframes floatup{to{transform:translate(-50%,-55px);opacity:0}}.battle-under{display:flex;justify-content:space-between;align-items:center;padding:10px 5px 0;color:#838293;font-size:9px;letter-spacing:.5px}.turn-order{display:flex;align-items:center;gap:6px}.turn-order span{margin-right:5px}.turn-dot{width:21px;height:21px;border-radius:50%;border:1px solid #4f4b60;display:grid;place-items:center;color:#c6bdca;background:#242333;font-size:9px}.turn-dot.current{border-color:var(--gold);color:var(--gold);box-shadow:0 0 9