const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){localStorage.setItem('eclipse-save',JSON.stringify(save));$('#currency').textContent=save.currency.toLocaleString();$('#stamina').textContent=save.stamina;$('#heroCount').textContent=String(save.owned.length).padStart(2,'0')}
function hero(id){return roster.find(h=>h.id===id)||roster[0]}
function avatar(h,enemy=false){let c=enemy?h.color:h.color, hair=enemy?'#80536d':h.hair;let face=enemy?`<path d="M35 42Q45 31 56 41L61 62 48 73 35 62Z" fill="#d3a29d"/><path d="M34 47Q28 22 49 24 68 25 61 48L55 39 40 42Z" fill="#372b46"/>`:`<path d="M34 43Q45 34 57 43L59 63 47 74 34 62Z" fill="#f1cbb6"/><path d="M31 49Q24 21 45 19 70 17 64 48L60 42 57 31Q43 39 34 36Z" fill="${hair}"/><path d="M33 40Q28 55 31 63L25 51Q24 31 34 26Z" fill="${hair}"/><path d="M58 39Q68 48 61 64L61 43Z" fill="${hair}"/><path d="M37 53h5m8 0h5" stroke="#593e58" stroke-width="2" stroke-linecap="round"/><path d="M43 63q4 3 8 0" fill="none" stroke="#c77683" stroke-width="1.5"/>`;
let costume=enemy?`<path d="M32 66 47 72 62 65 74 112 20 112Z" fill="#393246"/><path d="m33 72 14 12 13-13 8 41H26Z" fill="${c}"/><path d="m37 69 10 14 10-14 6 43H31Z" fill="#292538"/>`:`<path d="M34 66 47 72 60 66 74 113H20Z" fill="#352b40"/><path d="m34 69 13 12 13-12 9 44H25Z" fill="${c}"/><path d="m39 74 8 9 9-9 5 39H33Z" fill="#252233"/><path d="m33 70-12 9 9 15 10-12m18-12 13 8-7 14-9-10" fill="${hair}"/><path d="M42 84h10l4 29H39Z" fill="#e5c788" opacity=".8"/>`;
let weapon=enemy?'':h.weapon==='sword'?'<path d="m71 46 3-4 18 42-4 2Z" fill="#d9f4f3" stroke="#fff"/><path d="m82 82 7-3 5 7-9 4Z" fill="#d4b77a"/>':h.weapon==='staff'?'<path d="m70 39 3-1 6 76-5 1Z" fill="#dbbf83"/><circle cx="72" cy="36" r="7" fill="#b7ecf2" stroke="#fff" stroke-width="2"/>':h.weapon==='bow'?'<path d="M74 43Q101 75 75 104M74 43l18 57" fill="none" stroke="#e1c98b" stroke-width="3"/><path d="m75 41 2 67" stroke="#fff"/>':h.weapon==='scythe'?'<path d="m74 40 3 76m0-69q28-22 26 1-13-6-25 12" stroke="#dcdaef" stroke-width="4" fill="none"/><path d="m78 54 24-12q7 13-4 19" fill="#edb6e0"/>':'<path d="m70 38 3-1 7 78-5 1Z" fill="#d9e8ef"/><path d="M66 54h14m-13-4-1 9m14-9 1 9" stroke="#d5ba7b" stroke-width="3"/>';
return `<svg class="portrait" viewBox="0 0 110 120" aria-hidden="true"><defs><linearGradient id="g${h.id}${enemy?'e':''}" x2="0" y2="1"><stop stop-color="${c}" stop-opacity=".32"/><stop offset="1" stop-color="#171725" stop-opacity="0"/></linearGradient></defs><ellipse cx="48" cy="111" rx="33" ry="6" fill="#0a0a13" opacity=".6"/><path d="M7 110Q11 75 29 67L34 64 48 72 62 65Q83 75 89 112Z" fill="url(#g${h.id}${enemy?'e':''})"/>${costume}${face}${weapon}<path d="M36 58q10 6 20 0" fill="none" stroke="#ffe2d3" stroke-opacity=".55"/></svg>`}
function fighterMarkup(unit,idx,side){let ally=side==='ally', dead=unit.hp<=0, selected=ally?idx===selectedAlly:idx===selectedTarget;let h=ally?hero(unit.id):unit;return `<div class="fighter ${ally?'ally':'enemy'} ${dead?'dead':''} ${selected?'selected':''}" data-side="${side}" data-index="${idx}"><div class="portrait-wrap">${battle&&battle.current?.side===side&&battle.current?.index===idx?'<i class="turn-marker"></i>':''}<span class="element-badge">${h.element||'☾'}</span>${avatar(h,!ally)}</div><div class="fighter-name">${esc(h.name)}</div><div class="fighter-role">${ally?h.role:unit.title||'ABERRATION'}</div><div class="hp-track"><div class="hp-fill" style="width:${Math.max(0,unit.hp/unit.maxHp*100)}%"></div></div><div class="fighter-meta"><span>${Math.max(0,Math.ceil(unit.hp))}/${unit.maxHp}</span><span>${ally?'LV.'+h.level:unit.status||''}</span></div><div class="status-row">${unit.shield?'<span class="status-chip">✧ SHIELD</span>':''}${unit.burn?'<span class="status-chip" style="color:#ffa979">BURN</span>':''}</div></div>`}
function copyHero(h){let level=h.level+save.awakening;let max=Math.round(h.hp*(1+(level-1)*.055)*(1+save.awakening*.09));return{id:h.id,hp:max,maxHp:max,atk:Math.round(h.atk*(1+(level-1)*.04)*(1+save.weapon*.08)),spd:h.spd,energy:0,cd:0,shield:0}}
function spawnEnemies(){let scale=1+(save.stage-1)*.15;let seeds=mode==='boss'?[{name:'The Veil Devourer',kind:'boss',hp:4200,atk:215,spd:92,color:'#ce78ac',element:'☾',title:'WORLD-EATER'}]:enemySeeds.map(e=>({...e}));if(mode==='dungeon'){let n=3+Math.floor(Math.random()*2);seeds=Array.from({length:n},()=>({...enemySeeds[Math.floor(Math.random()*enemySeeds.length)]}))}return seeds.map((e,i)=>({id:'enemy'+i,name:e.name,kind:e.kind,hp:Math.round(e.hp*scale*(mode==='boss'?1:1)),maxHp:Math.round(e.hp*scale*(mode==='boss'?1:1)),atk:Math.round(e.atk*scale),spd:e.spd,element:e.element,color:e.color,title:e.title||'VEIL ABERRATION',energy:0,shield:0}))}
function startBattle(){if(!save.team.some(id=>save.owned.includes(id))){notify('Choose heroes for your squad first.');return}if(save.stamina<6){notify('Not enough stamina. Claim your daily reward!');return}save.stamina-=6;persist();let allies=save.team.slice(0,4).map(id=>copyHero(hero(id)));battle={allies,enemies:spawnEnemies(),round:1,current:null,turns:[],busy:false,won:false};selectedAlly=0;selectedTarget=0;makeQueue();render();notify(mode==='boss'?'The Veil Devourer emerges…':mode==='dungeon'?'The rift shifts around you…':'Battle begins. Choose a skill.');advanceTurn()}
function makeQueue(){let all=[...battle.allies.map((u,index)=>({side:'ally',index,spd:u.spd})),...battle.enemies.map((u,index)=>({side:'enemy',index,spd:u.spd}))].filter(t=>(t.side==='ally'?battle.allies:battle.enemies)[t.index].hp>0);battle.turns=all.sort((a,b)=>b.spd-a.spd);}
function living(side){return(side==='ally'?battle.allies:battle.enemies).filter(x=>x.hp>0)}
function advanceTurn(){if(!battle||battle.won)return;if(living('enemy').length===0){finishBattle(true);return}if(living('ally').length===0){finishBattle(false);return}if(!battle.turns.length){battle.round++;makeQueue()}let next=battle.turns.shift();let arr=next.side==='ally'?battle.allies:battle.enemies;if(arr[next.index].hp<=0){advanceTurn();return}battle.current=next;selectedAlly=next.side==='ally'?next.index:selectedAlly;if(next.side==='enemy'){render();setTimeout(()=>enemyAct(next.index),650)}else{render();if(auto)setTimeout(()=>{if(battle&&battle.current?.side==='ally')useSkill('basic')},420)}}
function affinity(attacker,target){let wheel=['✦','☾','❖','◇'];let a=wheel.indexOf(attacker),t=wheel.indexOf(target);return (a+1)%4===t?1.25:(t+1)%4===a?.8:1}
function damageTarget(target,amount,attacker,el){let crit=Math.random()<.16, power=amount*(crit?1.65:1)*(attacker?affinity(attacker.element,target.element):1);if(target.shield){let block=Math.min(target.shield,power);target.shield-=block;power-=block}target.hp=Math.max(0,target.hp-power);return{dmg:Math.round(power),crit}}
function effectFloat(side,index,text){let el=document.querySelectorAll(`.fighter.${side}`)[index];if(!el)return;let f=document.createElement('span');f.className='damage-float';f.textContent=text;el.append(f);setTimeout(()=>f.remove(),950)}
function pulse(side,index,cls='attacking'){let el=document.querySelectorAll(`.fighter.${side}`)[index];if(!el)return;el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);setTimeout(()=>el.classList.remove(cls),850)}
function useSkill(skill){if(!battle||actionLock||battle.current?.side!=='ally')return;let actor=battle.allies[battle.current.index],h=hero(actor.id);if(skill==='special'&&actor.cd>0){notify(`Special recharging: ${actor.cd} turn${actor.cd>1?'s':''}.`);return}if(skill==='ultimate'&&actor.energy<100){notify('Ultimate needs 100 resonance.');return}actionLock=true;let target=battle.enemies[selectedTarget];if(!target||target.hp<=0){selectedTarget=battle.enemies.findIndex(e=>e.hp>0);target=battle.enemies[selectedTarget]}if(!target){actionLock=false;finishBattle(true);return}let isUlt=skill==='ultimate';pulse('ally',battle.current.index,isUlt?'ultimate':'attacking');
if(isUlt){actor.energy=0;cameraFlash();if(h.id==='seraphine'){let amount=Math.round(actor.maxHp*.25);battle.allies.forEach((a,i)=>{a.hp=Math.min(a.maxHp,a.hp+amount);a.shield+=Math.round(amount*.65);effectFloat('ally',i,'+'+amount)})}else if(h.id==='nyx'){battle.enemies.forEach((e,i)=>{if(e.hp>0){let r=damageTarget(e,actor.atk*2.7,h);effectFloat('enemy',i,(r.crit?'CRIT ':'')+r.dmg);pulse('enemy',i,'hit')}})}else{let r=damageTarget(target,actor.atk*(h.rarity==='SSR'?4:3.1),h);effectFloat('enemy',selectedTarget,(r.crit?'CRIT ':'')+r.dmg);pulse('enemy',selectedTarget,'hit');if(h.id==='aurelia')actor.shield+=Math.round(actor.maxHp*.2)}}
else if(skill==='special'){actor.cd=2;actor.energy=Math.min(100,actor.energy+35);if(h.id==='seraphine'){let low=battle.allies.map((a,i)=>({a,i})).sort((x,y)=>x.a.hp/x.a.maxHp-y.a.hp/y.a.maxHp)[0];let heal=Math.round(low.a.maxHp*.34);low.a.hp=Math.min(low.a.maxHp,low.a.hp+heal);low.a.shield+=Math.round(heal*.35);effectFloat('ally',low.i,'+'+heal)}else if(h.id==='nyx'||h.id==='lune'){battle.enemies.forEach((e,i)=>{if(e.hp>0){let r=damageTarget(e,actor.atk*1.35,h);effectFloat('enemy',i,r.dmg);e.burn=1}})}else{let r=damageTarget(target,actor.atk*1.8,h);effectFloat('enemy',selectedTarget,(r.crit?'CRIT ':'')+r.dmg);if(h.id==='mira')actor.hp=Math.min(actor.maxHp,actor.hp+Math.round(r.dmg*.25))}}
else{actor.energy=Math.min(100,actor.energy+24);let r=damageTarget(target,actor.atk*(h.id==='kael'?1.25:1),h);effectFloat('enemy',selectedTarget,(r.crit?'CRIT ':'')+r.dmg);pulse('enemy',selectedTarget,'hit')}
// all actions build resonance for the whole party; opponents build it when attacked.
battle.allies.forEach((a,i)=>{if(i!==battle.current.index)a.energy=Math.min(100,a.energy+(isUlt?4:9))});battle.enemies.forEach(e=>{if(e.hp<=0)e.energy=Math.min(100,e.energy+12)});if(actor.cd>0&&skill!=='special')actor.cd--;if(actor.burn){actor.burn--}render();setTimeout(()=>{actionLock=false;if(living('enemy').length===0)finishBattle(true);else advanceTurn()},isUlt?1050:520)}
function cameraFlash(){let arena=$('.arena');if(arena){arena.classList.add('ultimate-scene');setTimeout(()=>arena.classList.remove('ultimate-scene'),850)}}
function enemyAct(idx){if(!battle)return;let e=battle.enemies[idx];if(!e||e.hp<=0){advanceTurn();return}let candidates=battle.allies.map((a,i)=>({a,i})).filter(x=>x.a.hp>0);let pick=candidates[Math.floor(Math.random()*candidates.length)];pulse('enemy',idx);let r=damageTarget(pick.a,e.atk,e);effectFloat('ally',pick.i,(r.crit?'CRIT ':'−')+r.dmg);pulse('ally',pick.i,'hit');if(pick.a.hp<=0)notify(`${hero(pick.a.id).name} has fallen!`);render();setTimeout(advanceTurn,640)}
function finishBattle(win){if(!battle||battle.won)return;battle.won=true;if(win){let reward=mode==='boss'?340:mode==='dungeon'?180:100+save.stage*14;save.currency+=reward;save.xp+=35+save.stage*8;save.cleared=Math.max(save.cleared,save.stage);save.inventory.push(mode==='boss'?'Voidglass Relic':mode==='dungeon'?'Riftbound Charm':'Ashen Sigil');let leveled=false;while(save.xp>=save.level*100){save.xp-=save.level*100;save.level++;leveled=true}persist();render();showResult(true,reward,leveled)}else{render();showResult(false,0,false)}}
function showResult(win,reward,leveled){let layer=$('#modalLayer');layer.innerHTML=`<div class="result-modal"><div class="eyebrow">${win?'VICTORY · THE VEIL RECEDES':'DEFEAT · REGROUP AND RISE'}</div><h2>${win?'A new dawn breaks':'The darkness endures'}</h2><p>${win?'Your squad earns a moment of peace. The journey continues.':'Your heroes need rest. Adjust your team and try again.'}${leveled?` Commander level up: ${save.level}!`:''}</p>${win?`<div class="loot-row"><div class="loot">✧<b>+${reward} Shards</b></div><div class="loot">◇<b>${mode==='boss'?'Voidglass Relic':mode==='dungeon'?'Riftbound Charm':'Ashen Sigil'}</b></div><div class="loot">✦<b>+${35+save.stage*8} XP</b></div></div>`:''}<button class="primary-btn" id="resultContinue">${win?'CONTINUE':'RETURN TO SANCTUARY'}</button></div>`;$('#resultContinue').onclick=()=>{layer.innerHTML='';battle=null;render()}}
function notify(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function render(){persist();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='battle')renderBattle();else if(view==='heroes')renderHeroes();else if(view==='summon')renderSummon();else renderRelics()}
function heading(kicker,title,note){return `<div class="view-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><div class="heading-note">${note}</div></div></div>`}
function renderBattle(){let m=$('#mainView');let stageName=mode==='boss'?'The Veil Devourer':mode==='dungeon'?'Riftbound Labyrinth':`The Shattered Causeway · ${String(save.stage).padStart(2,'0')}`;let ally=battle?battle.allies:save.team.slice(0,4).map(id=>copyHero(hero(id)));let enemies=battle?battle.enemies:enemySeeds.map((e,i)=>({...e,id:'preview'+i,maxHp:e.hp,hp:e.hp,title:'VEIL ABERRATION'}));if(battle&&enemies.length===1){enemies=[...enemies,{...enemySeeds[1],id:'echo',name:'Veil Echo',maxHp:1,hp:0,title:'BOUND SHADE'}]}
let actor=battle&&battle.current?.side==='ally'?battle.allies[battle.current.index]:null;let activeName=actor?hero(actor.id).name:'—';let skills=actor?`<button class="skill-btn" data-skill="basic"><span class="skill-symbol">⚔</span><b>Basic attack</b><small>Resonance +24</small></button><button class="skill-btn" data-skill="special" ${actor.cd>0?'disabled':''}><span class="skill-symbol">✧</span><b>Special</b><small>${actor.cd?`Cooldown ${actor.cd}`:'Resonance +35'}</small></button><button class="skill-btn ultimate ${actor.energy>=100?'ready':''}" data-skill="ultimate" ${actor.energy<100?'disabled':''}><span class="skill-symbol">☾</span><b>Ultimate</b><small>${actor.energy>=100?'READY':`Resonance ${actor.energy}%`}</small></button>`:`<button class="primary-btn start-battle" id="startBattle">${battle?'RESOLVE TURN':'BEGIN ENCOUNTER'} <span>· 6 ϟ</span></button>`;
m.innerHTML=`${heading('ASTRAL FRONTIER', 'The battlefield', 'Choose your heroes, master the turn order, and reclaim the fallen stars.')}<div class="battle-grid"><div><div class="arena"><div class="arena-stars"></div><div class="moon"></div><i class="ruin r1"></i><i class="ruin r2"></i><div class="arena-label">${mode==='boss'?'⚠ ABYSSAL THREAT':mode==='dungeon'?'✧ RIFT EXPEDITION':'✦ STORY · CHAPTER I'}</div><div class="wave-label">${battle?`ROUND <b>${battle.round}</b> · LIVE`:'WAVE 01 / 01'}</div><div class="arena-floor"></div><div class="battlefield"><div class="fighter-row enemy-row">${enemies.map((u,i)=>fighterMarkup(u,i,'enemy')).join('')}</div><div class="fighter-row ally-row">${ally.map((u,i)=>fighterMarkup(u,i,'ally')).join('')}</div></div></div><div class="battle-under"><div class="turn-order"><span>TURN ORDER</span>${(battle?.turns.slice(0,6)||[{side:'ally',index:0},{side:'enemy',index:0},{side:'ally',index:1},{side:'enemy',index:1}]).map(t=>{let u=(t.side==='ally'?ally:enemies)[t.index];return `<i class="turn-dot ${battle?.current?.side===t.side&&battle?.current?.index===t.index?'current':''}">${t.side==='ally'?hero(u.id).name[0]:u.name[0]}</i>`}).join('')}</div><div>ELEMENTS <span style="color:#eac589">✦</span> &gt; <span style="color:#b9a1dc">☾</span> &gt; <span style="color:#d795b4">❖</span> &gt; <span style="color:#9fe0d8">◇</span></div></div><div class="combat-panel"><div><div class="turn-status">${actor?`YOUR TURN · <b>${esc(activeName)}</b>`:battle?'ENEMY TURN · THE ABYSSAL HOST':'SQUAD READY · BEGIN WHEN YOU ARE'}</div><div class="skill-bar">${skills}</div></div><button class="auto-toggle ${auto?'on':''}" id="autoToggle">${auto?'◉ AUTO ON':'◎ AUTO OFF'}</button></div><div class="bottom-note">${actor?'Select a target on the field, then unleash a skill.':'Speed determines turn order · Choose a mode to begin your expedition.'}</div></div><div class="right-column"><div class="objective-card"><div class="card-kicker">CURRENT EXPEDITION</div><div class="stage-title">${stageName}</div><div class="stage-desc">${mode==='boss'?'A colossal presence stirs beneath the eclipse. Break its guard before the veil swallows all.':mode==='dungeon'?'Every descent changes the path. Defeat the riftborn and claim what they guard.':'The ancient road is swallowed by shadow. Push through the veil and find the missing scouts.'}</div><div class="stage-rewards"><span class="reward-chip">✧ ${mode==='boss'?'340':'100+'+save.stage*14}</span><span class="reward-chip">◇ Rare relic</span></div><div class="stage-switch"><button id="prevStage">‹</button><span>STAGE ${String(save.stage).padStart(2,'0')} / ∞</span><button id="nextStage">›</button></div></div><div class="party-card"><div class="party-head"><strong>Active squad</strong><button class="edit-team" data-view="heroes">EDIT TEAM ↗</button></div>${ally.map((u,i)=>{let h=hero(u.id);return `<div class="party-member"><div class="mini-portrait">${avatar(h)}</div><div class="member-info"><b>${esc(h.name)}</b><small>${h.role} · ${h.element}</small></div><span class="member-lvl">LV. ${h.level+save.awakening}</span></div>`}).join('')}</div></div></div>`;
$('#mainView').querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));$('#startBattle')?.addEventListener('click',startBattle);$('#autoToggle').onclick=()=>{auto=!auto;render();if(auto&&battle&&battle.current?.side==='ally')setTimeout(()=>useSkill('basic'),250)};$('#prevStage').onclick=()=>{save.stage=Math.max(1,save.stage-1);render()};$('#nextStage').onclick=()=>{save.stage++;render()};$('#mainView').querySelectorAll('.fighter').forEach(el=>el.onclick=()=>{let idx=+el.dataset.index;if(el.dataset.side==='enemy'&&battle&&battle.enemies[idx]?.hp>0){selectedTarget=idx;render()}else if(el.dataset.side==='ally'&&battle&&battle.current?.side==='ally'){selectedAlly=idx;notify('Choose a target for your skill.')}});$('#mainView').querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>useSkill(b.dataset.skill));
}

function renderHeroes(){let m=$('#mainView');m.innerHTML=`${heading('YOUR COMPANIONS','Hero archive',`${save.owned.length} awakened souls · Build a squad of four for the journey ahead.`)}<div class="team-strip"><div class="team-strip-head"><b>FORMATION</b><span>Choose a slot, then select a hero to assign.</span></div><div class="formation">${save.team.map((id,i)=>`<button class="formation-slot ${i===selectedAlly?'picked':''}" data-slot="${i}"><span class="slot-num">0${i+1}</span><span>${id?esc(hero(id).name):'EMPTY'}</span><small>${id?hero(id).role:'SELECT HERO'}</small></button>`).join('')}</div></div><div class="archive-tools"><span>OWNED · ${save.owned.length} / ${roster.length}</span><span>✦ SSR <b>${save.owned.filter(id=>hero(id).rarity==='SSR').length}</b>　 ◇ SR <b>${save.owned.filter(id=>hero(id).rarity==='SR').length}</b>　 R <b>${save.owned.filter(id=>hero(id).rarity==='R').length}</b></span></div><div class="collection-grid">${save.owned.map(id=>{let h=hero(id);let xp=save.xp;return `<article class="hero-card ${save.team.includes(id)?'in-team':''}" data-heroid="${id}"><div class="hero-art"><span class="rarity">${h.rarity} · ${h.element}</span>${avatar(h)}</div><div class="hero-data"><span class="card-level">LV. ${h.level+save.awakening}</span><b>${esc(h.name)}</b><p>${h.title} · ${h.role}</p><div class="hero-stats"><span>ATK ${Math.round(h.atk*(1+save.weapon*.08))}</span><span>HP ${Math.round(h.hp*(1+save.awakening*.09))}</span><span>SPD ${h.spd}</span></div><button class="upgrade hero-upgrade" data-upgrade="${id}">↗ TRAIN · 80 ✧</button></div></article>`}).join('')}</div>`;
m.querySelectorAll('.formation-slot').forEach(b=>b.onclick=()=>{selectedAlly=+b.dataset.slot;renderHeroes()});m.querySelectorAll('.hero-card').forEach(c=>c.onclick=e=>{if(e.target.closest('.hero-upgrade'))return;let id=c.dataset.heroid;let existing=save.team.indexOf(id);if(existing>=0){if(existing===selectedAlly){save.team[existing]=null;notify('Squad slot cleared.')}else{[save.team[selectedAlly],save.team[existing]]=[save.team[existing],save.team[selectedAlly]];notify('Formation updated.') }}else{save.team[selectedAlly]=id;notify(`${hero(id).name} joins the squad.`)}save.team=save.team.slice(0,4);persist();renderHeroes()});m.querySelectorAll('.hero-upgrade').forEach(b=>b.onclick=e=>{e.stopPropagation();let h=hero(b.dataset.upgrade);if(save.currency<80){notify('Not enough shards to train.');return}if(h.level>=60){notify('This hero has reached the level cap.');return}save.currency-=80;h.level++;save.xp=Math.max(0,save.xp-8);persist();notify(`${h.name} reached level ${h.level}!`);renderHeroes()})}
function renderSummon(){let m=$('#mainView');m.innerHTML=`${heading('ASTRAL CONVERGENCE','Call the stars',`Summon new heroes to your cause. ${save.currency.toLocaleString()} Astral Shards available.`)}<div class="summon-layout"><div class="summon-banner"><div class="banner-copy"><div class="eyebrow">LIMITED · CELESTIAL VEIL</div><h2>Where starlight<br>meets shadow.</h2><p>The veil grows thin. Answer the call and welcome a legendary soul into your company.</p><div class="banner-feature">Vesper Noct <small>SSR · ECLIPSE REAPER · RATE UP</small></div><div class="summon-actions"><button class="primary-btn" data-pull="1">✧ SINGLE SUMMON · 160</button><button class="secondary-btn" data-pull="10">TENFOLD · 1,440</button></div></div></div><div class="summon-side"><h3>Convergence rates</h3><div class="rate-row"><span class="rate-star">★★★★★</span><b>SSR</b><small>3% · 1.5% rate-up</small></div><div class="rate-row"><span class="rate-star" style="color:#c6a9dc">★★★★</span><b>SR</b><small>17%</small></div><div class="rate-row"><span class="rate-star" style="color:#a7a5b8">★★★</span><b>R</b><small>80%</small></div><div class="pity-box"><span>ASTRAL PITY</span><b>${save.owned.filter(id=>hero(id).rarity==='SSR').length?0:0} / 80</b><div class="pity-line"><i></i></div></div><div class="summon-disclaimer">Every 10-fold guarantees at least one SR or higher. Shards are earned through battles—no purchases, no pressure. Your journey is the reward.</div></div></div><div class="summon-footer">✦ NEW HEROES JOIN YOUR ARCHIVE AUTOMATICALLY · DUPLICATES BECOME ASTRAL SHARDS</div>`;m.querySelectorAll('[data-pull]').forEach(b=>b.onclick=()=>summon(+b.dataset.pull))}
function summon(count){let cost=count===10?1440:160;if(save.currency<cost){notify(`You need ${cost-save.currency} more Astral Shards.`);return}save.currency-=cost;let pulls=[];for(let i=0;i<count;i++){let r=Math.random(),rarity=r<.03?'SSR':r<.2?'SR':'R';if(i===count-1&&count===10&&!pulls.some(x=>x.rarity!=='R'))rarity='SR';let candidates=roster.filter(h=>h.rarity===rarity);if(rarity==='SSR'&&Math.random()<.5)candidates=[hero('vesper')];let unit=candidates[Math.floor(Math.random()*candidates.length)];let dupe=save.owned.includes(unit.id);if(!dupe){save.owned.push(unit.id);unit.level=1}else{save.currency+=rarity==='SSR'?400:rarity==='SR'?120:45}pulls.push({...unit,dupe})}persist();renderSummon();let layer=$('#modalLayer');layer.innerHTML=`<div class="result-modal"><div class="eyebrow">ASTRAL CONVERGENCE</div><h2>The stars have answered</h2><p>${count} soul${count>1?'s':''} emerged from the veil.${pulls.some(x=>x.rarity==='SSR')?' A legendary presence stirs…':''}</p><div class="summon-result">${pulls.map(h=>`<div class="result-unit" style="border-color:${h.rarity==='SSR'?'#ddb969':h.rarity==='SR'?'#b98acf':'#77778c'}">${avatar(h)}<b>${esc(h.name.split(' ')[0])}${h.dupe?' · DUPE':''}</b><small>${h.rarity}</small></div>`).join('')}</div><button class="primary-btn" id="summonClose">CONTINUE</button></div>`;$('#summonClose').onclick=()=>{layer.innerHTML='';renderSummon()}}
function renderRelics(){let all=[['Astral Edge','Weapon · Lv. '+(1+save.weapon),'Increase all heroes’ attack by 8% per level.','⚔'],['Veilglass Sigil','Relic · SSR','A fragment of the first eclipse. Critical resonance flows within.','✧'],['Warden’s Oath','Relic · SR','An ancient promise sealed in silver. Strengthens the front line.','◇'],['Starfall Bloom','Relic · SR','A flower preserved from a world before the veil.','❀']];let m=$('#mainView');m.innerHTML=`${heading('ARMORY & ECHOES','Relics & equipment','Strengthen your chosen heroes with artifacts found beyond the veil.')}<div class="gear-summary"><div><div class="card-kicker">EQUIPMENT POWER</div><b>+${save.weapon*8}% <small>ATK · SQUAD WIDE</small></b></div><div><div class="card-kicker">AWAKENING</div><b>${save.awakening} <small>RITUALS COMPLETE</small></b></div><div class="gear-actions"><button class="secondary-btn" id="weaponUpgrade">UPGRADE WEAPON · 180 ✧</button><button class="primary-btn" id="awaken">AWAKEN SQUAD · 500 ✧</button></div></div><div class="inventory-grid">${all.map((r,i)=>`<article class="relic-card"><div class="relic-icon">${r[3]}</div><span class="card-level">${i===0?'LV. '+(save.weapon+1):i===1?'SSR':i===2?'SR':'SR'}</span><b>${r[0]}</b><p>${r[1]} · ${r[2]}</p>${i===0?`<button class="upgrade" id="weaponUpgrade2">UPGRADE · 180 ✧</button>`:`<button class="upgrade" data-wear="${i}">${save.inventory.length?`OWNED · ${save.inventory.filter(x=>x===r[0]).length}`:'EQUIP TO SQUAD'}</button>`}</article>`).join('')}</div><div class="inventory-foot"><span>DISCOVERED RELICS</span><b>${save.inventory.length} / ∞</b><span class="inventory-names">${save.inventory.length?save.inventory.slice(-5).map(esc).join('　·　'):'Win battles to find relics and materials.'}</span></div>`;$('#weaponUpgrade').onclick=upgradeWeapon;$('#weaponUpgrade2').onclick=upgradeWeapon;$('#awaken').onclick=()=>{if(save.currency<500){notify('Need 500 Astral Shards for awakening.');return}if(save.awakening>=5){notify('Squad awakening is complete.');return}save.currency-=500;save.awakening++;persist();notify('Awakening complete · all heroes grow stronger.');renderRelics()};m.querySelectorAll('[data-wear]').forEach(b=>b.onclick=()=>notify(save.inventory.length?'Relic resonance attuned to your lead hero.':'Find relics by winning battles.'))}
function upgradeWeapon(){if(save.currency<180){notify('Need 180 Astral Shards to upgrade.');return}save.currency-=180;save.weapon++;persist();notify(`Astral Edge enhanced to level ${save.weapon+1}.`);renderRelics()}
function setView(v){view=v;render()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#staminaPlus').onclick=()=>{save.stamina=Math.min(60,save.stamina+12);persist();notify('Daily rift reward claimed · +12 stamina.')};persist();render();

