=='boss'?'340':'100+'+save.stage*14}</span><span class="reward-chip">◇ Rare relic</span></div><div class="stage-switch"><button id="prevStage">‹</button><span>STAGE ${String(save.stage).padStart(2,'0')} / ∞</span><button id="nextStage">›</button></div></div><div class="party-card"><div class="party-head"><strong>Active squad</strong><button class="edit-team" data-view="heroes">EDIT TEAM ↗</button></div>${ally.map(u=>{let h=hero(u.id);return `<div class="party-member"><div class="mini-portrait">${avatar(h)}</div><div class="member-info"><b>${esc(h.name)}</b><small>${h.role} · ${h.element}</small></div><span class="member-lvl">LV. ${h.level+save.awakening}</span></div>`}).join('')}</div></div></div>`;m.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));m.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{if(battle){notify('Finish the current battle first.');return}mode=x.dataset.mode;render()});$('#startBattle')?.addEventListener('click',startBattle);$('#autoToggle').onclick=()=>{auto=!auto;render();if(auto&&battle&&battle.current?.side==='ally')setTimeout(()=>useSkill('basic'),250)};$('#prevStage').onclick=()=>{save.stage=Math.max(1,save.stage-1);render()};$('#nextStage').onclick=()=>{save.stage++;render()};m.querySelectorAll('.fighter').forEach(el=>el.onclick=()=>{let idx=+el.dataset.index;if(el.dataset.side==='enemy'&&battle&&battle.enemies[idx]?.hp>0){selectedTarget=idx;render()}else if(el.dataset.side==='ally'&&battle&&battle.current?.side==='ally'){selectedAlly=idx;notify('Choose a target for your skill.')}});m.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>useSkill(b.dataset.skill))}
function useSkill(skill){if(!battle||actionLock||battle.current?.side!=='ally')return;let actor=battle.allies[battle.current.index],h=hero(actor.id);if(skill==='special'&&actor.cd>0){notify(`Special recharging: ${actor.cd} turns.`);return}if(skill==='ultimate'&&actor.energy<100){notify('Ultimate needs 100 resonance.');return}actionLock=true;let target=battle.enemies[selectedTarget];if(!target||target.hp<=0){selectedTarget=battle.enemies.findIndex(e=>e.hp>0);target=battle.enemies[selectedTarget]}if(!target){actionLock=false;finishBattle(true);return}let isUlt=skill==='ultimate';pulse('ally',battle.current.index,isUlt?'ultimate':'attacking');if(isUlt){actor.energy=0;cameraFlash();if(h.id==='seraphine'){let amount=Math.round(actor.maxHp*.25);battle.allies.forEach((a,i)=>{a.hp=Math.min(a.maxHp,a.hp+amount);a.shield+=Math.round(amount*.65);effectFloat('ally',i,'+'+amount)})}else if(h.id==='nyx'){battle.enemies.forEach((e,i)=>{if(e.hp>0){let r=damageTarget(e,actor.atk*2.7,h);effectFloat('enemy',i,(r.crit?'CRIT ':'')+r.dmg);pulse('enemy',i,'hit')}})}else{let r=damageTarget(target,actor.atk*(h.rarity==='SSR'?4:3.1),h);effectFloat('enemy',selectedTarget,(r.crit?'CRIT ':'')+r.dmg);pulse('enemy',selectedTarget,'hit');if(h.id==='aurelia')actor.shield+=Math.round(actor.maxHp*.2)}}else if(skill==='special'){actor.cd=2;actor.energy=Math.min(100,actor.energy+35);if(h.id==='seraphine'){let low=battle.allies.map((a,i)=>({a,i})).filter(x=>x.a.hp>0).sort((x,y)=>x.a.hp/x.a.maxHp-y.a.hp/y.a.maxHp)[0];if(low){let heal=Math.round(low.a.maxHp*.34);low.a.hp=Math.min(low.a.maxHp,low.a.hp+heal);low.a.shield+=Math.round(heal*.35);effectFloat('ally',low.i,'+'+heal)}}else if(h.id==='nyx'||h.id==='lune'){battle.enemies.forEach((e,i)=>{if(e.hp>0){let r=damageTarget(e,actor.atk*1.35,h);effectFloat('enemy',i,r.dmg);e.burn=1}})}else{let r=damageTarget(target,actor.atk*1.8,h);effectFloat('enemy',selectedTarget,(r.crit?'CRIT ':'')+r.dmg);if(h.id==='mira')actor.hp=Math.min(actor.maxHp,actor.hp+Math.round(r.dmg*.25))}}else{actor.energy=Math.min(100,actor.energy+24);let r=damageTarget(target,actor.atk*(h.id==='kael'?1.25:1),h);effectFloat('enemy',selectedTarget,(r.crit?'CRIT ':'')+r.dmg);pulse('enemy',selectedTarget,'hit')}battle.allies.forEach((a,i)=>{if(i!==battle.current.index)a.energy=Math.min(100,a.energy+(isUlt?4:9))});battle.enemies.forEach(e=>{if(e.hp<=0)e.energy=Math.min(100,e.energy+12)});if(actor.cd>0&&skill!=='special')actor.cd--;render();setTimeout(()=>{actionLock=false;if(living('enemy').length===0)finishBattle(true);else advanceTurn()},isUlt?1050:520)}
function enemyAct(idx){if(!battle)return;let e=battle.enemies[idx];if(!e||e.hp<=0){advanceTurn();return}let candidates=battle.allies.map((a,i)=>({a,i})).filter(x=>x.a.hp>0);if(!candidates.length){finishBattle(false);return}let pick=candidates[Math.floor(Math.random()*candidates.length)],r=damageTarget(pick.a,e.atk,e);effectFloat('ally',pick.i,(r.crit?'CRIT ':'−')+r.dmg);pulse('ally',pick.i,'hit');render();setTimeout(advanceTurn,640)}
function finishBattle(win){if(!battle||battle.won)return;battle.won=true;if(win){let reward=mode==='boss'?340:mode==='dungeon'?180:100+save.stage*14;save.currency+=reward;save.xp+=35+save.stage*8;save.cleared=Math.max(save.cleared,save.stage);save.inventory.push(mode==='boss'?'Voidglass Relic':mode==='dungeon'?'Riftbound Charm':'Ashen Sigil');while(save.xp>=save.level*100){save.xp-=save.level*100;save.level++}persist();render();showResult(true,reward)}else{render();showResult(false,0)}}
function showResult(win,reward){let layer=$('#modalLayer');layer.innerHTML=`<div class="result-modal"><div class="eyebrow">${win?'VICTORY · THE VEIL RECEDES':'DEFEAT · REGROUP AND RISE'}</div><h2>${win?'A new dawn breaks':'The darkness endures'}</h2><p>${win?'Your squad earns a moment of peace. The journey continues.':'Your heroes need rest. Adjust your team and try again.'}</p>${win?`<div class="loot-row"><div class="loot">✧<b>+${reward} Shards</b></div><div class="loot">◇<b>${mode==='boss'?'Voidglass Relic':mode==='dungeon'?'Riftbound Charm':'Ashen Sigil'}</b></div><div class="loot">✦<b>+${35+save.stage*8} XP</b></div></div>`:''}<button class="primary-btn" id="resultContinue">${win?'CONTINUE':'RETURN TO SANCTUARY'}</button></div>`;$('#resultContinue').onclick=()=>{layer.innerHTML='';battle=null;render()}}
