+ {id:'mira',name:'Mira Solenne',title:'Wildheart',rarity:'R',element:'❖',role:'Druid',hp:1300,atk:173,spd:107,color:'#a8d9a1',hair:'#677f53',level:1,desc:'The forest answers her call.',weapon:'bow'}
+];
+const enemySeeds=[{name:'Veil Imp',kind:'imp',hp:710,atk:105,spd:96,color:'#d38baa',element:'☾'},{name:'Hollow Knight',kind:'knight',hp:1150,atk:145,spd:75,color:'#b9a5d0',element:'◇'},{name:'Ashen Wisp',kind:'wisp',hp:620,atk:130,spd:120,color:'#81cfd1',element:'✦'},{name:'Rift Hound',kind:'hound',hp:890,atk:138,spd:110,color:'#d39475',element:'❖'}];
+const defaults={currency:1240,stamina:38,owned:['aurelia','nyx','kael','seraphine'],team:['aurelia','nyx','kael','seraphine'],stage:1,xp:0,level:12,weapon:0,awakening:0,cleared:0,inventory:[]};
+let save;try{save={...defaults,...JSON.parse(localStorage.getItem('eclipse-save')||'{}')}}catch(e){save={...defaults}}
+let view='battle',mode='story',battle=null,selectedTarget=0,selectedAlly=0,auto=false,actionLock=false,toastTimer;
+const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
+function persist(){localStorage.setItem('eclipse-save',JSON.stringify(save));$('#currency').textContent=save.currency.toLocaleString();$('#stamina').textContent=save.stamina;$('#heroCount').textContent=String(save.owned.length).padStart(2,'0')}
+function hero(id){return roster.find(h=>h.id===id)||roster[0]}
+function avatar(h,enemy=false){let c=h.color||'#c58aad',hair=enemy?'#80536d':(h.hair||'#d9c6e0');let face=enemy?'<path d="M35 42Q45 31 56 41L61 62 48 73 35 62Z" fill="#d3a29d"/><path d="M34 47Q28 22 49 24 68 25 61 48L55 39 40 42Z" fill="#372b46"/>':`<path d="M34 43Q45 34 57 43L59 63 47 74 34 62Z" fill="#f1cbb6"/><path d="M31 49Q24 21 45 19 70 17 64 48L60 42 57 31Q43 39 34 36Z" fill="${hair}"/><path d="M33 40Q28 55 31 63L25 51Q24 31 34 26Z" fill="${hair}"/><path d="M58 39Q68 48 61 64L61 43Z" fill="${hair}"/><path d="M37 53h5m8 0h5" stroke="#593e58" stroke-width="2" stroke-linecap="round"/><path d="M43 63q4 3 8 0" fill="none" stroke="#c77683" stroke-width="1.5"/>`;let costume=enemy?`<path d="M32 66 47 72 62 65 74 112 20 112Z" fill="#393246"/><path d="m33 72 14 12 13-13 8 41H26Z" fill="${c}"/><path d="m37 69 10 14 10-14 6 43H31Z" fill="#292538"/>`:`<path d="M34 66 47 72 60 66 74 113H20Z" fill="#352b40"/><path d="m34 69 13 12 13-12 9 44H25Z" fill="${c}"/><path d="m39 74 8 9 9-9 5 39H33Z" fill="#252233"/><path d="m33 70-12 9 9 15 10-12m18-12 13 8-7 14-9-10" fill="${hair}"/><path d="M42 84h10l4 29H39Z" fill="#e5c788" opacity=".8"/>`;let weapon=enemy?'':h.weapon==='sword'?'<path d="m71 46 3-4 18 42-4 2Z" fill="#d9f4f3" stroke="#fff"/><path d="m82 82 7-3 5 7-9 4Z" fill="#d4b77a"/>':h.weapon==='staff'?'<path d="m70 39 3-1 6 76-5 1Z" fill="#dbbf83"/><circle cx="72" cy="36" r="7" fill="#b7ecf2" stroke="#fff" stroke-width="2"/>':h.weapon==='bow'?'<path d="M74 43Q101 75 75 104M74 43l18 57" fill="none" stroke="#e1c98b" stroke-width="3"/><path d="m75 41 2 67" stroke="#fff"/>':h.weapon==='scythe'?'<path d="m74 40 3 76m0-69q28-22 26 1-13-6-25 12" stroke="#dcdaef" stroke-width="4" fill="none"/><path d="m78 54 24-12q7 13-4 19" fill="#edb6e0"/>':'<path d="m70 38 3-1 7 78-5 1Z" fill="#d9e8ef"/><path d="M66 54h14m-13-4-1 9m14-9 1 9" stroke="#d5ba7b" stroke-width="3"/>';return `<svg class="portrait" viewBox="0 0 110 120" aria-hidden="true"><ellipse cx="48" cy="111" rx="33" ry="6" fill="#0a0a13" opacity=".6"/><path d="M7 110Q11 75 29 67L34 64 48 72 62 65Q83 75 89 112Z" fill="${c}" opacity=".25"/>${costume}${face}${weapon}<path d="M36 58q10 6 20 0" fill="none" stroke="#ffe2d3" stroke-opacity=".55"/></svg>`}
+function copyHero(h){let level=h.level+save.awakening,max=Math.round(h.hp*(1+(level-1)*.055)*(1+save.awakening*.09));return{id:h.id,hp:max,maxHp:max,atk:Math.round(h.atk*(1+(level-1)*.04)*(1+save.weapon*.08)),spd:h.spd,energy:0,cd:0,shield:0}}
+function spawnEnemies(){let scale=1+(save.stage-1)*.15,seeds=mode==='boss'?[{name:'The Veil Devourer',kind:'boss',hp:4200,atk:215,spd:92,color:'#ce78ac',element:'☾',title:'WORLD-EATER'}]:enemySeeds.map(e=>({...e}));if(mode==='dungeon')seeds=Array.from({length:3+Math.floor(Math.random()*2)},()=>({...enemySeeds[Math.floor(Math.random()*enemySeeds.length)]}));return seeds.map((e,i)=>({id:'enemy'+i,name:e.name,kind:e.kind,hp:Math.round(e.hp*scale),maxHp:Math.round(e.hp*scale),atk:Math.round(e.atk*scale),spd:e.spd,element:e.element,color:e.color,title:e.title||'VEIL ABERRATION',energy:0,shield:0}))}
+function fighterMarkup(unit,idx,side){let ally=side==='ally',dead=unit.hp<=0,selected=ally?idx===selectedAlly:idx===selectedTarget,h=ally?hero(unit.id):unit;return `<div class="fighter ${ally?'ally':'enemy'} ${dead?'dead':''} ${selected?'selected':''}" data-side="${side}" data-index="${idx}"><div class="portrait-wrap">${battle&&battle.current?.side===side&&battle.current?.index===idx?'<i class="turn-marker"></i>':''}<span class="element-badge">${h.element||'☾'}</span>${avatar(h,!ally)}</div><div class="fighter-name">${esc(h.name)}</div><div class="fighter-role">${ally?h.role:unit.title||'ABERRATION'}</div><div class="hp-track"><div class="hp-fill" style="width:${Math.max(0,unit.hp/unit.maxHp*100)}%"></div></div><div class="fighter-meta"><span>${Math.max(0,Math.ceil(unit.hp))}/${unit.maxHp}</span><span>${ally?'LV.'+h.level:unit.status||''}</span></div><div class="status-row">${unit.shield?'<span class="status-chip">✧ SHIELD</span>':''}${unit.burn?'<span class="status-chip" style="color:#ffa979">BURN</span>':''}</div></div>`}
+function heading(kicker,title,note){return `<div class="view-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><div class="heading-note">${note}</div></div></div>`}
+function notify(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+function setView(v){view=v;render()}
+function render(){persist();document.querySelectorAll('.nav-item,.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='battle')renderBattle();else if(view==='heroes')renderHeroes();else if(view==='summon')renderSummon();else renderRelics()}
+function startBattle(){if(!save.team.some(id=>id&&save.owned.includes(id))){notify('Choose heroes for your squad first.');return}if(save.stamina<6){notify('Not enough stamina. Claim your daily reward!');return}save.stamina-=6;persist();let allies=save.team.filter(id=>id&&save.owned.includes(id)).slice(0,4).map(id=>copyHero(hero(id)));while(allies.length<4)allies.push(copyHero(hero('seraphine')));battle={allies,enemies:spawnEnemies(),round:1,current:null,turns:[],busy:false,won:false};selectedAlly=0;selectedTarget=0;makeQueue();render();notify(mode==='boss'?'The Veil Devourer emerges…':mode==='dungeon'?'The rift shifts around you…':'Battle begins. Choose a skill.');advanceTurn()}
+function living(side){return(side==='ally'?battle.allies:battle.enemies).filter(x=>x.hp>0)}
+function makeQueue(){battle.turns=[...battle.allies.map((u,index)=>({side:'ally',index,spd:u.spd})),...battle.enemies.map((u,index)=>({side:'enemy',index,spd:u.spd}))].filter(t=>(t.side==='ally'?battle.allies:battle.enemies)[t.index].hp>0).sort((a,b)=>b.spd-a.spd)}
+function advanceTurn(){if(!battle||battle.won)return;if(!living('enemy').length){finishBattle(true);return}if(!living('ally').length){finishBattle(false);return}if(!battle.turns.length){battle.round++;makeQueue()}let next=battle.turns.shift(),arr=next.side==='ally'?battle.allies:battle.enemies;if(arr[next.index].hp<=0){advanceTurn();return}battle.current=next;if(next.side==='ally'){selectedAlly=next.index;render();if(auto)setTimeout(()=>{if(battle&&battle.current?.side==='ally')useSkill('basic')},420)}else{render();setTimeout(()=>enemyAct(next.index),650)}}
+function affinity(attacker,target){let wheel=['✦','☾','❖','◇'],a=wheel.indexOf(attacker),t=wheel.indexOf(target);return(a+1)%4===t?1.25:(t+1)%4===a?.8:1}
+function damageTarget(target,amount,attacker){let crit=Math.random()<.16,power=amount*(crit?1.65:1)*(attacker?affinity(attacker.element,target.element):1);if(target.shield){let block=Math.min(target.shield,power);target.shield-=block;power-=block}target.hp=Math.max(0,target.hp-power);return{dmg:Math.round(power),crit}}
+function effectFloat(side,index,text){let el=document.querySelectorAll(`.fighter.${side}`)[index];if(!el)return;let f=document.createElement('span');f.className='damage-float';f.textContent=text;el.append(f);setTimeout(()=>f.remove(),950)}
